<?php
session_start();
require_once __DIR__ . '/../lead-engine/config.php';
if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/?next='.rawurlencode($_SERVER['REQUEST_URI']??'/dashboard/goliath-lead-brain.php'));exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sbq($ep){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json'],CURLOPT_TIMEOUT=>25]);$b=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$d=json_decode($b,true);return ($http>=200&&$http<300&&is_array($d))?$d:[];}
$key=defined('AFTER_HOURS_CRON_KEY')?AFTER_HOURS_CRON_KEY:'timetomakethedonuts';
$leads=sbq('goliath_lead_brain?select=*&order=heat_score.desc,created_at.desc&limit=40');
$journeyRows=sbq('goliath_lead_journey?select=*&order=stage_order.asc&limit=1200');
$artifactRows=sbq('goliath_lead_artifacts?select=*&order=created_at.desc&limit=300');
$cmdRows=sbq('goliath_command_bus?select=*&order=created_at.desc&limit=120');
$journey=[];foreach($journeyRows as $j){$journey[$j['lead_id']][]=$j;}
$artifacts=[];foreach($artifactRows as $a){$artifacts[$a['lead_id']][]=$a;}
$cmds=[];foreach($cmdRows as $c){$cmds[$c['lead_id']??'system'][]=$c;}
function progress_pct($rows){if(!$rows)return 0;$done=0;foreach($rows as $r){if(($r['status']??'')==='complete')$done++;}return min(100,round(($done/max(1,count($rows)))*100));}
function heat_class($score){return $score>=85?'hot':($score>=60?'warm':'cool');}
$hot=0;$pipeline=0;$queued=0;foreach($leads as $l){if((int)($l['heat_score']??0)>=85)$hot++;$pipeline+=(float)($l['pipeline_value']??0);}foreach($cmdRows as $c){if(($c['status']??'')==='queued')$queued++;}
