<section class="top lbTop"><div><h1>Lead Brain</h1><p>Every lead becomes a living intelligence file: evidence, content, emails, video, next action and appointment priority.</p></div><div class="brandbar"><button class="btn" id="createTestLead">Create Test Lead</button><a class="btn dark" href="/dashboard/goliath-mission-control.php">Mission Control</a></div></section>
<section class="lbPulse"><div><b><?=count($leads)?></b><span>Total Leads</span></div><div class="hot"><b><?=$hot?></b><span>Hot Leads</span></div><div><b>$<?=number_format($pipeline,0)?></b><span>Pipeline Estimate</span></div><div><b><?=$queued?></b><span>Agent Commands</span></div></section>
<section class="lbLayout"><div class="lbBoard"><div class="lbBoardHead"><h2>Lead Battlefield</h2><span>Red → Green journey proof</span></div><?php if(!$leads): ?><article class="lbEmpty"><h2>No Lead Brain files yet</h2><p>Click Create Test Lead to create Jim Anderson, Montana → Westport. Goliath will create the journey rows and queue every agent.</p></article><?php endif; ?><?php foreach($leads as $lead): $id=$lead['id'];$rows=$journey[$id]??[];$pct=progress_pct($rows);$heat=heat_class((int)($lead['heat_score']??0)); $towns=implode(', ', is_array($lead['target_towns']??null)?$lead['target_towns']:[]);?><article class="lbLeadCard <?=$heat?>" data-lead='<?=h(json_encode($lead,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE))?>' data-journey='<?=h(json_encode($rows,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE))?>' data-artifacts='<?=h(json_encode($artifacts[$id]??[],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE))?>' data-commands='<?=h(json_encode($cmds[$id]??[],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE))?>' onclick="selectLead(this)"><div class="lbLeadTop"><div><strong><?=h($lead['name']??'New Lead')?></strong><span><?=h(ucfirst($lead['lead_type']??'lead'))?> · <?=h(($lead['current_state']??'Unknown').' → '.($towns?:'Needs town'))?></span></div><em><?=h($lead['heat_score']??50)?></em></div><div class="lbPipeline"><i style="width:<?=$pct?>%"></i></div><div class="lbChips"><span><?=h($lead['budget']??'Budget ?')?></span><span><?=h($lead['timeline']??'Timeline ?')?></span><span><?=h($lead['assigned_agent']??'Jessica')?></span></div><div class="lbMiniStages"><?php foreach($rows as $r): ?><span class="<?=h($r['status']??'pending')?>" title="<?=h($r['title']??$r['stage'])?>"></span><?php endforeach;?></div></article><?php endforeach;?></div>
